const L = wall_length, bl = bag_length, bh = bag_height, bd = bl * 0.55, j = jitter, s = seed;
for (let r = 0; r < Math.round(rows); r++) {
  const off = r % 2 ? bl / 2 : 0, n = Math.max(1, Math.floor((L - off + 1e-6) / bl));
  for (let i = 0; i < n; i++) {
    const id = r * 100 + i;
    const q = addpoint(0, [off + bl * (i + 0.5) + (rand(id, s, 1) - 0.5) * 0.04 * j, bh * 0.5 + r * bh * 0.82, (rand(id, s, 2) - 0.5) * 0.06 * j]);
    setpointattrib(0, 'scale', q, [bl * (0.96 + 0.06 * rand(id, s, 3)), bh, bd]);
    setpointattrib(0, 'orient', q, quaternion(radians((rand(id, s, 4) - 0.5) * 12 * j), [0, 1, 0]));
    setpointattrib(0, 'tint', q, 0.85 + 0.25 * rand(id, s, 5));
  }
}
